'use strict';
/* Fast SELL-only optimizer for Exhaustion Q490. BUY stays untouched. Research only; no live edits. */
const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';
const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function atr(c,p=14){const a=Array(c.length).fill(NaN),q=[];let s=0;for(let i=1;i<c.length;i++){const tr=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c));q.push(tr);s+=tr;if(q.length>p)s-=q.shift();if(q.length===p)a[i]=s/p}return a}
function adx(c,p=14){const o=Array(c.length).fill(NaN),tr=Array(c.length).fill(0),pd=Array(c.length).fill(0),md=Array(c.length).fill(0);for(let i=1;i<c.length;i++){const up=c[i].h-c[i-1].h,dn=c[i-1].l-c[i].l;pd[i]=up>dn&&up>0?up:0;md[i]=dn>up&&dn>0?dn:0;tr[i]=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c))}let tn=0,pn=0,mn=0;for(let i=1;i<=p;i++){tn+=tr[i];pn+=pd[i];mn+=md[i]}const dx=Array(c.length).fill(NaN);for(let i=p;i<c.length;i++){if(i>p){tn=tn-tn/p+tr[i];pn=pn-pn/p+pd[i];mn=mn-mn/p+md[i]}if(tn>0){const a=100*pn/tn,b=100*mn/tn;if(a+b>0)dx[i]=100*Math.abs(a-b)/(a+b)}}let seed=0,n=0,last=NaN;for(let i=p;i<c.length;i++){if(!Number.isFinite(dx[i]))continue;if(n<p){seed+=dx[i];n++;if(n===p)last=o[i]=seed/p}else last=o[i]=(last*(p-1)+dx[i])/p}return o}
const A=atr(M),X=adx(M),BASE={burst:2.6,w:.30,r:.15,ax:32,bm:.50,blocks:[1,5,23]};
function run(q){let out=[],p=null;for(let i=250;i<M.length-1;i++){if(p){const b=M[i],sl=b.h>=p.sl,tp=b.l<=p.tp;if(sl||tp||i-p.ei+1>=3){const px=sl?p.sl:tp?p.tp:b.c;out.push({t:p.t,r:(p.en-px)/p.risk,h:p.h});p=null}}if(p)continue;const ex=i-1;if(!Number.isFinite(A[ex])||!Number.isFinite(X[ex]))continue;const hr=new Date(M[ex].t).getUTCHours();if(q.blocks.includes(hr)||X[ex]>q.ax)continue;const b=M[ex],rg=b.h-b.l;if(!(rg>0)||Math.abs(b.c-b.o)/rg>q.bm)continue;const disp=M[ex-1].c-M[ex-3].c;if(!(disp>0)||disp<A[ex]*q.burst)continue;let agree=0;for(let k=ex-3;k<ex;k++)if(M[k].c>M[k].o)agree++;if(agree<2)continue;const uw=(b.h-Math.max(b.o,b.c))/rg;if(uw<q.w)continue;const cf=M[i];if(cf.c>=b.h-rg*q.r||cf.h>b.h+A[ex]*.25)continue;const en=M[i+1].o,risk=Math.max(A[ex]*1.75,2),reward=Math.max(A[ex]*1.5,2);p={en,risk,sl:en+risk,tp:en-reward,ei:i+1,t:M[i].t,h:hr}}return out}
function S(a){let w=0,gp=0,gl=0,e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else if(x.r<0){gl-=x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}
const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
const B=run(BASE),bs=S(B);console.log('EXHAUSTION Q490 — SELL FAST OPTIMIZER');console.log('BASE',F(bs));if(!(bs.n===52&&Math.abs(bs.wr-57.7)<.2)){console.log('❌ BASE PARITY FAIL');process.exit(3)}
const end=M.at(-1).t, vals={burst:[2.4,2.6,2.8,3.0],w:[.25,.30,.35,.40],r:[.10,.15,.20,.25],ax:[26,28,30,32],bm:[.40,.45,.50,.55]};
let cand=[];for(const burst of vals.burst)for(const w of vals.w)for(const r of vals.r)for(const ax of vals.ax)for(const bm of vals.bm){const q={burst,w,r,ax,bm,blocks:[1,5,23]},a=run(q),s=S(a),r90=S(a.filter(x=>x.t>=end-90*864e5)),r180=S(a.filter(x=>x.t>=end-180*864e5));if(s.n<35||s.net<=0||s.dd>4.5)continue;let folds=0;for(let k=0;k<4;k++){const lo=M[Math.floor(M.length*k/4)].t,hi=k===3?Infinity:M[Math.floor(M.length*(k+1)/4)].t,z=S(a.filter(x=>x.t>=lo&&x.t<hi));if(z.n>=6&&z.net>0)folds++}const score=s.wr*2+s.pf*8+s.net*.3+r90.pf*2+r180.pf+folds*2-s.dd;cand.push({q,s,r90,r180,folds,score})}
cand.sort((a,b)=>b.score-a.score);console.log('\n🏆 TOP 20 SELL CANDIDATES');cand.slice(0,20).forEach((x,i)=>console.log(`${String(i+1).padStart(2)} | burst>=${x.q.burst} wick>=${x.q.w} retrace=${x.q.r} ADX<=${x.q.ax} body<=${x.q.bm} | ${F(x.s)} | 180D ${F(x.r180)} | 90D ${F(x.r90)} | folds ${x.folds}/4`));
console.log('\nUTC HOUR DIAGNOSTIC — BASE SELL');for(let h=0;h<24;h++){const z=S(B.filter(x=>x.h===h));if(z.n)console.log(`${String(h).padStart(2,'0')} UTC | ${F(z)}`)}
